initialize.fn:
function(instance, context) {
    instance.data.ready = false;
    if (!window.HibiraBubbleChat) {
        instance.publishState('error', 'The Hibira Live Chat runtime did not load.');
        return;
    }
    instance.data.onChange = function (error) {
        if (error) {
            instance.publishState('error', error);
            instance.triggerEvent('error');
            return;
        }
        instance.data.announced = true;
        instance.publishState('error', '');
        instance.publishState('ready', true);
        instance.triggerEvent('ready');
    };
    window.HibiraBubbleChat.onChange(instance.data.onChange);
    instance.data.ready = true;
}

update.fn:
function(instance, properties, context) {
    if (!instance.data.ready) return;
    var chat = window.HibiraBubbleChat;
    var error = chat.load({
        workspace: context.keys['Workspace ID'],
        show_button: properties.show_button,
        color: properties.color,
        language: properties.language
    });
    if (error) {
        instance.publishState('error', error);
        instance.triggerEvent('error');
    } else if (chat.isReady() && !instance.data.announced) {
        instance.data.announced = true;
        instance.publishState('ready', true);
        instance.triggerEvent('ready');
    }
}

preview.fn:
function(instance, properties) {
    instance.canvas.append($('<div></div>').text('Hibira Live Chat').css({
        font: '12px/1.4 system-ui, sans-serif', color: '#7f1d1d', background: '#fee2e2',
        border: '1px dashed #f87171', borderRadius: '6px', padding: '6px 8px',
        height: '100%', boxSizing: 'border-box', overflow: 'hidden', whiteSpace: 'nowrap'
    }));
}

code.fn:
function(instance, properties, context) {
    if (!instance.data.ready) return;
    var id = String(properties.user_id || '').trim();
    var hash = String(properties.user_hash || '').trim();
    if (!id || !hash) {
        instance.publishState('error', 'Identify visitor needs User ID and User hash.');
        instance.triggerEvent('error');
        return;
    }
    window.HibiraBubbleChat.identify({ id: id, hash: hash, name: String(properties.name || ''), email: String(properties.email || '') });
}

server.fn:
async function(properties, context) {
  const crypto = require('crypto');
  const secret = String((context.keys || {})['Identity secret'] || '').trim();
  const userId = String(properties.user_id || '').trim();
  if (!secret) return { user_hash: '', error: 'Paste the identity secret (lcid_...) in Plugins > Hibira Live Chat. Create it under Settings > Widget > Verified visitors on chat.hibira.io.' };
  if (!userId) return { user_hash: '', error: 'User ID is empty: use Current User\'s unique id, and run this only when the user is logged in.' };
  return { user_hash: crypto.createHmac('sha256', secret).update(userId).digest('hex'), error: '' };
}
